#!/usr/bin/env python3
# Changes only the independent examples AI click handler and its local helper.
from pathlib import Path
p=Path('/var/www/hebrewverbs-clean/verbs.html')
s=p.read_text(encoding='utf-8')
old="if(t.closest('#alwaysAiCodeAI')){var q=el('verbSearch')?.value.trim();if(!q)return;choose(q);var a=el('alwaysAiCodeAI');a.href='https://chatgpt.com/?q='+encodeURIComponent(prompt());return;}"
new="if(t.closest('#alwaysAiCodeAI')){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();var q=el('verbSearch')?.value.trim();if(!q)return;choose(q);examplesAiGenerate(q);return;}"
helper=" // Automatic examples: only replaces the manual ChatGPT opening in this section.\n var examplesAiBusy=false;\n function examplesAiNotice(message){\n  var root=el('independentExamplesScreen');if(!root)return;\n  render([]);var note=document.createElement('div');note.className='independent-note';\n  note.textContent=message;root.appendChild(note);\n }\n function examplesAiWords(value){return String(value||'').normalize('NFKC').replace(/[\\u0591-\\u05c7]/g,'').match(/[\\u05d0-\\u05ea]+/g)||[];}\n function examplesAiMatches(sentence,forms){\n  var words=examplesAiWords(sentence);\n  return forms.some(function(form){\n   var parts=examplesAiWords(form);\n   return parts.length>0&&parts.some(function(part){return words.indexOf(part)!==-1;});\n  });\n }\n async function examplesAiGenerate(query){\n  if(examplesAiBusy)return;\n  var rec=match(query),data=rec&&rec.data||{},inf=data.infinitive||{};\n  var order=['present','past','future','imperative'];\n  var forms={};\n  order.forEach(function(tense){forms[tense]=(Array.isArray(data[tense])?data[tense]:[]).map(function(r){return r&&r.he||'';}).filter(Boolean);});\n  if(order.some(function(t){return !forms[t].length;})){\n   examplesAiNotice('Для автоматических примеров необходимо полное спряжение выбранного глагола.');return;\n  }\n  examplesAiBusy=true;\n  var ai=el('alwaysAiCodeAI');if(ai)ai.setAttribute('aria-busy','true');\n  examplesAiNotice('AI создаёт примеры…');\n  var rows={},used={};\n  try{\n   for(var i=0;i<order.length;i++){\n    var tense=order[i];\n    var labels={present:'настоящем времени',past:'прошедшем времени',future:'будущем времени',imperative:'повелительном наклонении'};\n    var sample=forms[tense].slice(0,6).join(', ');\n    var topic='Глагол '+(inf.he||query)+' ('+(inf.ru||query)+'). Создай предложения ИСКЛЮЧИТЕЛЬНО в '+labels[tense]+'. Используй одну из точных форм глагола: '+sample+'. Каждое предложение должно содержать такую форму с правильными огласовками, и переводы ru, uk, en. Не используй другие времена.';\n    var response=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({section:'examples',topic:topic,level:'beginner'}),cache:'no-store'});\n    if(!response.ok)throw Error('HTTP '+response.status);\n    var result=await response.json(),items=result&&result.sentences;\n    if(!Array.isArray(items))throw Error('Ответ AI не содержит предложений');\n    var found=items.find(function(r){return r&&['he','ru','uk','en'].every(function(k){return typeof r[k]==='string'&&r[k].trim();})&&examplesAiMatches(r.he,forms[tense])&&!used[examplesAiWords(r.he).join(' ')];});\n    if(!found)throw Error('AI не создал проверенный пример: '+labels[tense]);\n    rows[tense]={he:found.he,ru:found.ru,uk:found.uk,en:found.en};\n    used[examplesAiWords(found.he).join(' ')]=true;\n   }\n   if(!document.body.classList.contains('independent-examples-mode')||!el('verbSearch')||el('verbSearch').value.trim()!==query)return;\n   render(order.map(function(t){return rows[t];}));displayed=true;\n  }catch(error){\n   examplesAiNotice('Не удалось создать четыре правильных примера: '+(error&&error.message||error));\n  }finally{examplesAiBusy=false;if(ai)ai.removeAttribute('aria-busy');}\n }\n"
anchor=" window.addEventListener('click',function(e){if(!document.body.classList.contains('independent-examples-mode'))return;"
if s.count(old)!=1 or s.count(anchor)!=1:
    raise SystemExit('STOP: page differs from inspected version; nothing changed')
s=s.replace(anchor,helper+anchor,1).replace(old,new,1)
p.write_text(s,encoding='utf-8')
print('OK: only Examples AI request automated; API, conjugations and other sections unchanged; no backup created')
